<?php
declare(strict_types=1);
namespace Hostider\Support\Advanced;
use Hostider\Core\{Id,Idempotency,Validation,CanonicalJson};
use Hostider\Core\Http\HttpError;
use Hostider\Support\{Access,Service};
use Hostider\Support\Automation\{Ast,Engine};
use Hostider\Support\Work\{Eligibility,Policy};
final readonly class Commands
{
    public function __construct(private Common $m){}
    private function fields(string $action,array $p): array
    {
        $keys=match($action){'rule-publish'=>['id','department_id','customer_id','sample_ticket_id','version','spec'],'incident-new'=>['department_id','version','title','description','private_root','affected'],'incident-update'=>['id','version','status','public_update','private_root'],'incident-link'=>['ticket_id','version','incident_id'],'priority'=>['ticket_id','version','value','reason'],'csat-policy'=>['department_id','version','window_seconds'],default=>throw new HttpError(422,'ADVANCED_ACTION_INVALID')};Validation::fields($p,$keys,$keys);foreach(['id','department_id','customer_id','ticket_id','sample_ticket_id','incident_id'] as $key){if(isset($p[$key])){Access::id($p[$key]);}}Common::version($p['version'],in_array($action,['rule-publish','incident-new','csat-policy'],true));
        if($action==='rule-publish'){$p['spec']=Ast::rule(Common::object($p['spec']));}if($action==='incident-new'){if($p['version']!==0){throw new HttpError(409,'INCIDENT_NEW_VERSION');}Common::text($p['title'],191);foreach(['description','private_root','affected'] as $k){Common::text($p[$k],4000,true);}}if($action==='incident-update'){if(!in_array($p['status'],Incidents::STATES,true)){throw new HttpError(422,'INCIDENT_STATUS_INVALID');}Common::text($p['public_update']);Common::text($p['private_root'],4000,true);}if($action==='priority'){Ast::action(['kind'=>'priority','value'=>$p['value']]);Common::text($p['reason'],500);}if($action==='csat-policy'){Policy::integer($p['window_seconds'],1,31536000);}return $p;
    }
    private function state(string $action,array $p,array $u,array $s): array
    {
        $db=$this->m->c->db;
        if($action==='rule-publish'){$this->m->access->department($p['department_id']);$this->m->scoped($u,$s,$p['department_id'],$p['customer_id'],'support.automation.manage');$sample=$this->m->access->ticket($u,$s,$p['sample_ticket_id'],'support.automation.manage');if($sample['customer_id']!==$p['customer_id']||$sample['department_id']!==$p['department_id']){throw new HttpError(404,'SUPPORT_NOT_FOUND');}foreach($p['spec']['actions'] as $a){$perm=match($a['kind']){'assign'=>'support.ticket.assign','note'=>'support.ticket.internal_note','incident'=>'support.incident.manage',default=>'support.ticket.manage'};$this->m->scoped($u,$s,$p['department_id'],$p['customer_id'],$perm);}$r=$db->execute('SELECT * FROM support_rule_heads WHERE id=? FOR UPDATE',[$p['id']])->fetch();if($r&&($r['department_id']!==$p['department_id']||$r['customer_id']!==$p['customer_id'])){throw new HttpError(404,'SUPPORT_NOT_FOUND');}if((int)($r['version']??0)!==$p['version']){throw new HttpError(409,'RULE_VERSION_CONFLICT');}if(!$r&&(int)$db->execute('SELECT COUNT(*) FROM support_rule_heads WHERE department_id=? AND customer_id=?',[$p['department_id'],$p['customer_id']])->fetchColumn()>=16){throw new HttpError(409,'RULE_SCOPE_LIMIT');}return ['head'=>$r?:null,'ticket_version'=>(int)$sample['version'],'evaluation'=>(new Engine($this->m))->evaluate($u,$s,$sample,$p['spec'])];}
        if($action==='incident-new'){$this->m->department($u,$s,$p['department_id'],'support.incident.manage');return ['department'=>$this->m->access->department($p['department_id'])['version']];}
        if($action==='incident-update'){$r=(new Incidents($this->m))->row($u,$s,$p['id']);if((int)$r['version']!==$p['version']){throw new HttpError(409,'INCIDENT_VERSION_CONFLICT');}return ['id'=>$r['id'],'version'=>(int)$r['version'],'status'=>$r['status']];}
        if($action==='csat-policy'){$this->m->access->management($u,$s);$this->m->department($u,$s,$p['department_id'],'support.incident.manage');$r=$db->execute('SELECT * FROM support_csat_policies WHERE department_id=? FOR UPDATE',[$p['department_id']])->fetch();if((int)($r['version']??0)!==$p['version']){throw new HttpError(409,'CSAT_POLICY_VERSION_CONFLICT');}return $r?:['version'=>0];}
        $t=$this->m->access->ticket($u,$s,$p['ticket_id'],'support.ticket.manage');if((int)$t['version']!==$p['version']){throw new HttpError(409,'SUPPORT_VERSION_CONFLICT');}if($action==='incident-link'){$incident=(new Incidents($this->m))->linkable($u,$s,$t,$p['incident_id']);return ['ticket_version'=>(int)$t['version'],'incident_version'=>(int)$incident['version']];}(new Operations($this->m))->preflight($u,$s,$t,['kind'=>'priority','value'=>$p['value']]);return ['ticket_version'=>(int)$t['version'],'effective_priority'=>$t['effective_priority'],'work'=>$db->execute('SELECT version,policy_id,assignee_id FROM support_work_tickets WHERE ticket_id=?',[$t['id']])->fetch()];
    }
    public function command(string $ref,string $route,array $body,string $key,string $trace): array
    {
        $this->m->gate();if(!in_array($route,['prepare','execute'],true)){throw new HttpError(422,'ADVANCED_ROUTE_INVALID');}Validation::fields($body,['action','payload','confirmation'],['action','payload']);if(!is_string($body['action'])){throw new HttpError(422,'ADVANCED_ACTION_INVALID');}$action=$body['action'];$p=$this->fields($action,Common::object($body['payload']));$work=function(bool $replay)use($ref,$route,$body,$action,$p,$trace){(new Eligibility($this->m->c))->fence();return $this->m->c->identity->withStepUp($ref,'admin',function($u,$s)use($ref,$route,$body,$action,$p,$trace,$replay){
            // A replay must reauthorize, but does not require the old optimistic version.
            if($replay){if($action==='rule-publish'){$this->m->scoped($u,$s,$p['department_id'],$p['customer_id'],'support.automation.manage');$this->m->access->ticket($u,$s,$p['sample_ticket_id'],'support.automation.manage');foreach($p['spec']['actions'] as $a){$perm=match($a['kind']){'assign'=>'support.ticket.assign','note'=>'support.ticket.internal_note','incident'=>'support.incident.manage',default=>'support.ticket.manage'};$this->m->scoped($u,$s,$p['department_id'],$p['customer_id'],$perm);}}elseif($action==='incident-update'){(new Incidents($this->m))->row($u,$s,$p['id']);}elseif(in_array($action,['incident-new','csat-policy'],true)){$this->m->department($u,$s,$p['department_id'],'support.incident.manage');if($action==='csat-policy'){$this->m->access->management($u,$s);}}else{$t=$this->m->access->ticket($u,$s,$p['ticket_id'],'support.ticket.manage');if($action==='incident-link'){$this->m->scoped($u,$s,$t['department_id'],$t['customer_id'],'support.incident.manage');}}return [];}
            $state=$this->state($action,$p,$u,$s);$db=$this->m->c->db;if($route==='prepare'){$id=Id::uuid();$db->execute('INSERT INTO support_advanced_confirmations(id,actor_id,session_id,identity_version,action,payload_hmac,state_hmac,expires_at) VALUES (?,?,?,?,?,?,?,TIMESTAMPADD(SECOND,300,UTC_TIMESTAMP(6)))',[$id,$u['id'],$s['id'],$u['identity_version'],$action,$this->m->hash($p),$this->m->hash($state)]);$this->m->c->identity->confirmationEvent($u['id'],$id,false);return ['id'=>$id,'action'=>$action,'expires_in'=>300,'effect'=>'TEST_ONLY_NO_CUSTOMER_MAIL_OR_PROVIDER','evaluation'=>$state['evaluation']??null];}
            $a=Common::object($body['confirmation']??[]);Validation::fields($a,['id','accepted'],['id','accepted']);Access::id($a['id']);if($a['accepted']!==true){throw new HttpError(403,'CONFIRMATION_REQUIRED');}$r=$db->execute('SELECT *,UNIX_TIMESTAMP(expires_at) expiry FROM support_advanced_confirmations WHERE id=? FOR UPDATE',[$a['id']])->fetch();if(!$r||$r['used_at']!==null||$r['actor_id']!==$u['id']||$r['session_id']!==$s['id']||(int)$r['identity_version']!==(int)$u['identity_version']||$r['action']!==$action||(int)$r['expiry']<=time()||!hash_equals($r['payload_hmac'],$this->m->hash($p))||!hash_equals($r['state_hmac'],$this->m->hash($state))){throw new HttpError(409,'ADVANCED_CONFIRMATION_INVALID');}$db->execute('UPDATE support_advanced_confirmations SET used_at=UTC_TIMESTAMP(6) WHERE id=?',[$r['id']]);$result=$this->apply($ref,$u,$s,$action,$p,$trace);$this->m->c->identity->confirmationEvent($u['id'],$r['id'],true);return $result;});};return (new Idempotency($this->m->c->db))->run($ref,'support-advanced:'.$route,$key,['hmac'=>$this->m->hash($body)],fn()=>$work(false),fn()=>$work(true));
    }
    private function apply(string $ref,array $u,array $s,string $action,array $p,string $trace): array
    {
        $db=$this->m->c->db;$actor=$this->m->access->actor($u,$s);
        if($action==='rule-publish'){if($p['version']===0){$db->execute('INSERT INTO support_rule_heads(id,department_id,customer_id) VALUES (?,?,?)',[$p['id'],$p['department_id'],$p['customer_id']]);}$id=Id::uuid();$v=$p['version']+1;$db->execute('INSERT INTO support_rule_revisions(id,rule_id,revision,spec,enabled,ordering,sponsor_id,session_id,identity_version) VALUES (?,?,?,?,?,?,?,?,?)',[$id,$p['id'],$v,CanonicalJson::encode($p['spec']),(int)$p['spec']['enabled'],$p['spec']['order'],$u['id'],$s['id'],$u['identity_version']]);$db->execute('UPDATE support_rule_heads SET revision_id=?,version=? WHERE id=?',[$id,$v,$p['id']]);$this->m->event($p['department_id'],$p['id'],'RULE_PUBLISHED',$actor,$trace,['revision_id'=>$id,'version'=>$v]);return ['id'=>$p['id'],'revision_id'=>$id,'version'=>$v];}
        if($action==='incident-new'){return (new Incidents($this->m))->create($u,$s,$p,$trace);}if($action==='incident-update'){return (new Incidents($this->m))->update($u,$s,$p,$trace);}
        if($action==='csat-policy'){$v=$p['version']+1;$db->execute('INSERT INTO support_csat_policies VALUES (?,?,?) ON DUPLICATE KEY UPDATE window_seconds=VALUES(window_seconds),version=VALUES(version)',[$p['department_id'],$p['window_seconds'],$v]);$this->m->event($p['department_id'],$p['department_id'],'CSAT_POLICY',$actor,$trace,['version'=>$v,'window_seconds'=>$p['window_seconds']]);return ['version'=>$v];}
        $t=$this->m->access->ticket($u,$s,$p['ticket_id'],'support.ticket.manage');if($action==='incident-link'){(new Incidents($this->m))->link($u,$s,$t,$p['incident_id'],$trace);}else{(new Operations($this->m))->apply($ref,$u,$s,$t,['kind'=>'priority','value'=>$p['value']],$trace);$this->m->event($t['department_id'],$t['id'],'PRIORITY_REASON',$actor,$trace,['reason_encrypted'=>$this->m->crypto->encrypt($p['reason'],'priority-reason:'.$t['id'])],$t);}return ['id'=>$t['id'],'version'=>(int)$db->execute('SELECT version FROM support_tickets WHERE id=?',[$t['id']])->fetchColumn()];
    }
}
